export function evaluate(source) {
  if (typeof source !== "string") {
    throw new TypeError("Expression must be a string");
  }

  const tokens = [];
  const tokenPattern = /(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?|\*\*|[()+*/-]/y;
  let offset = 0;

  while (offset < source.length) {
    if (/\s/.test(source[offset])) {
      offset++;
      continue;
    }

    tokenPattern.lastIndex = offset;
    const match = tokenPattern.exec(source);
    if (!match) {
      throw new SyntaxError(`Unexpected character at position ${offset}`);
    }
    tokens.push(match[0]);
    offset = tokenPattern.lastIndex;
  }

  let position = 0;

  function parsePrimary() {
    const token = tokens[position];

    if (token === "(") {
      position++;
      const value = parseExpression();
      if (tokens[position] !== ")") {
        throw new SyntaxError("Expected closing parenthesis");
      }
      position++;
      return value;
    }

    if (token !== undefined && /^(?:\d|\.)/.test(token)) {
      position++;
      return Number(token);
    }

    throw new SyntaxError("Expected a number or parenthesized expression");
  }

  function parsePower() {
    const base = parsePrimary();
    if (tokens[position] === "**") {
      position++;
      return base ** parseUnary();
    }
    return base;
  }

  function parseUnary() {
    const token = tokens[position];
    if (token === "+" || token === "-") {
      position++;
      const value = parseUnary();
      return token === "-" ? -value : value;
    }
    return parsePower();
  }

  function parseProduct() {
    let value = parseUnary();
    while (tokens[position] === "*" || tokens[position] === "/") {
      const operator = tokens[position++];
      const right = parseUnary();
      value = operator === "*" ? value * right : value / right;
    }
    return value;
  }

  function parseExpression() {
    let value = parseProduct();
    while (tokens[position] === "+" || tokens[position] === "-") {
      const operator = tokens[position++];
      const right = parseProduct();
      value = operator === "+" ? value + right : value - right;
    }
    return value;
  }

  const result = parseExpression();
  if (position !== tokens.length) {
    throw new SyntaxError("Unexpected token");
  }
  if (!Number.isFinite(result)) {
    throw new RangeError("Expression result must be finite");
  }
  return result;
}
